package dev.imagh.pft.ledger.transaction

/**
 * Where a transaction came from. Only [MANUAL] has an entry point in slice C; each other source gets
 * its own in the slice that builds it (recurring in E2, SMS and email in M1b, import in I1).
 */
enum class TxnSource {
    /** Typed in by the user. */
    MANUAL,

    /** Parsed from a bank SMS on the device. */
    SMS,

    /** Parsed from a bank email on the device. */
    EMAIL,

    /** Imported from another app's export. */
    IMPORT,

    /** Generated by a recurring rule. */
    RECURRING,
}
